SELECT t1.ACCT_NAME AS "account",t0.sym AS "sym",t0.price AS "price" FROM trading.trades AS t0 LEFT OUTER JOIN ref_data.account_master AS t1 ON (t1.ID = t0.account_id AND t1.in_z <= '2030-01-01 00:00:00' AND (t1.out_z > '2030-01-01 00:00:00' OR t1.out_z IS NULL)) WHERE t0.price > 250.0 AND t0.in_z <= '2030-01-01 00:00:00' AND (t0.out_z > '2030-01-01 00:00:00' OR t0.out_z IS NULL) ORDER BY t0.price ASC NULLS FIRST
